import{_ as t,o,c as r,ag as a}from"./chunks/framework.BIas3y6W.js";const g=JSON.parse('{"title":"Self-Paced Path","description":"","frontmatter":{"source":"resources/self-paced.md"},"headers":[],"relativePath":"resources/self-paced.md","filePath":"resources/self-paced.md"}'),s={name:"resources/self-paced.md"};function n(i,e,h,d,l,u){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="self-paced-path" tabindex="-1">Self-Paced Path <a class="header-anchor" href="#self-paced-path" aria-label="Permalink to &quot;Self-Paced Path&quot;">​</a></h1><blockquote><p>How to do Building Apps with AI without a class: on your own from the public materials, as the only student in a section, or catching up on a studio you missed. Everything in the course is written to work without an instructor. This page says what replaces each studio activity, what to do instead of every pair activity, and how to check yourself.</p></blockquote><p><strong>On this page:</strong> <a href="#who-this-is-for">Who this is for</a> · <a href="#how-much-time">Time</a> · <a href="#each-week-in-order">Each week</a> · <a href="#what-replaces-the-studio">What replaces the studio</a> · <a href="#working-alone-every-pair-activity">Working alone?</a> · <a href="#using-tutor-mode">Tutor mode</a> · <a href="#checking-yourself-the-six-skills">Checking yourself</a> · <a href="#your-private-writing">Your private writing</a> · <a href="#if-you-fall-behind">Falling behind</a></p><hr><h2 id="who-this-is-for" tabindex="-1">Who this is for <a class="header-anchor" href="#who-this-is-for" aria-label="Permalink to &quot;Who this is for&quot;">​</a></h2><ul><li><strong>Learning on your own from the public course.</strong> You have no instructor, no Canvas and no grades, but you can do every lab, homework and project. The rules about AI use, safety and privacy still apply, because they protect <em>you</em>. Start with the <a href="./../setup/safety-contract.html">safety contract</a> and the <a href="./../setup/">week 0 setup</a>, and check the age and region notes in <a href="./../TOOLS.html">Tool Handout</a>: some free tools are 18+ or not available everywhere.</li><li><strong>Enrolled, but the only student (or one of very few).</strong> Your instructor posts the substitutions for your course on Canvas in week 1, such as a practice spec and a practice pull request with known issues to find. This page tells you what each one replaces. Where a line below says <em>Enrolled</em>, follow it; where it says <em>On your own</em>, that&#39;s for independent learners.</li><li><strong>Enrolled, and you missed a studio.</strong> Do the lab&#39;s <strong>Core</strong> parts on your own using this page, then follow the make-up rules in the <a href="./../SYLLABUS.html#missed-studios-and-make-up-work">syllabus</a>. Online or in another time zone for part of the course? Talk to your instructor in week 1 (<a href="./../SYLLABUS.html#missed-studios-and-make-up-work">syllabus</a>).</li></ul><p><strong>What you need first.</strong> The course assumes you&#39;ve taken one programming course in any language (often Python), or have the same experience another way: you can write a loop, a condition and a function. It doesn&#39;t assume you know HTML, CSS, JavaScript, the terminal, git or how the web works; the course teaches those. If you know Python but not JavaScript, work through <a href="./../setup/python-to-javascript.html">From Python to JavaScript</a> in week 0 (about 60–90 minutes).</p><p>Using a screen reader or only a keyboard? See the <a href="./accessibility.html">accessibility guide</a> first.</p><h2 id="how-much-time" tabindex="-1">How much time <a class="header-anchor" href="#how-much-time" aria-label="Permalink to &quot;How much time&quot;">​</a></h2><p>The course is built for about <strong>8.5 hours a week for 16 weeks</strong>: two 75-minute studios plus about 6 hours outside class. Weeks 1–15 teach; week 16 is the Project Fair and the final submission. On your own, the studio time becomes lab time, so the total is about the same (about 135 hours). Two common ways to fit it in:</p><table tabindex="0"><thead><tr><th>Pace</th><th>Hours a week</th><th>Notes</th></tr></thead><tbody><tr><td><strong>16 weeks</strong></td><td>about 8–9</td><td>The course as designed: one course week per calendar week. Do Studio A&#39;s lab early in the week and Studio B&#39;s a few days later, so you practice each skill twice</td></tr><tr><td><strong>8 weeks</strong></td><td>about 15–17</td><td>Two course weeks per calendar week, paired 1+2, 3+4, … 15+16 (the course&#39;s accelerated version). Do both Studio A labs, then both Studio B labs, and never split a timed activity</td></tr></tbody></table><p>The first time you use any tool takes longer than the stated times. Going slower is fine. Skipping the AI-off checks is not: they&#39;re how you find out what you actually learned.</p><h2 id="each-week-in-order" tabindex="-1">Each week, in order <a class="header-anchor" href="#each-week-in-order" aria-label="Permalink to &quot;Each week, in order&quot;">​</a></h2><ol><li><strong>Read the week&#39;s <code>README.md</code></strong>, starting with <strong>This week at a glance</strong>. It lists what&#39;s due, the AI rules for the week, and the <strong>Minimum to keep up</strong>.</li><li><strong>Before Studio A:</strong> the README and at most one short reading (about 30 minutes).</li><li><strong>Studio A:</strong> go through <code>slides.md</code> (the concept talk), then the <strong>Studio A</strong> section of <code>lab.md</code>. Do the <strong>Core</strong> parts first; <strong>If time</strong> parts are optional.</li><li><strong>Studio B:</strong> the <strong>Studio B</strong> section of <code>lab.md</code>.</li><li><strong>Instead of the exit ticket</strong> (weeks 1–14): answer the README&#39;s <strong>Understanding check</strong> with the AI off, before looking anything up. Then, from memory, explain one function or decision from the project you worked on <strong>two weeks earlier</strong> in two or three sentences, and check yourself against the code. Weeks 15 and 16 have no exit ticket.</li><li><strong>Homework:</strong> the core tier of <code>homework.md</code>. Do the <strong>Minimum to keep up</strong> box first.</li><li><strong>Reflection:</strong> write it with the AI off, using the <a href="./../templates/REFLECTION.html">reflection template</a>. Keep it private (<a href="#your-private-writing">where</a>).</li></ol><p>Every lab uses the <a href="./safe-loop.html">Safe Loop</a>. Keep it next to your keyboard.</p><h2 id="what-replaces-the-studio" tabindex="-1">What replaces the studio <a class="header-anchor" href="#what-replaces-the-studio" aria-label="Permalink to &quot;What replaces the studio&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In a studio</th><th>On your own</th></tr></thead><tbody><tr><td><strong>Recap</strong> of last week&#39;s most-missed question</td><td>Re-answer the question from last week&#39;s Understanding check that you found hardest, from memory</td></tr><tr><td><strong>Concept talk</strong></td><td><code>slides.md</code> and the README&#39;s <strong>Key ideas</strong></td></tr><tr><td><strong>Live demo</strong></td><td>Do the lab&#39;s first part slowly, with the <a href="./safe-loop.html">Safe Loop</a> in front of you</td></tr><tr><td><strong>Help from the instructor or a TA</strong></td><td><a href="./troubleshooting.html">Troubleshooting</a>, then the <a href="./safe-loop.html#the-two-strikes-rule">two-strikes rule</a>, then <a href="#using-tutor-mode">tutor mode</a></td></tr><tr><td><strong>Checkpoint share</strong></td><td>Take a screenshot at each ✅ checkpoint and keep it with your notes. If you&#39;re stuck, write down the exact blocker: that counts too</td></tr><tr><td><strong>Show and tell</strong></td><td>Show a friend and explain one thing the AI got wrong</td></tr><tr><td><strong>Debrief</strong></td><td>Three lines in your notes: what worked, what didn&#39;t, what you&#39;d do differently</td></tr><tr><td><strong>Exit ticket</strong> (🔴 AI off)</td><td>The README&#39;s Understanding check and the delayed-recall question (<a href="#each-week-in-order">step 5</a>)</td></tr><tr><td><strong>Debug Clinic</strong> (week 7)</td><td>🔴 AI off for 10 minutes per bug, then the kit&#39;s <a href="https://github.com/Boyu-Zhang-UOI/vc101-debug-clinic/blob/main/hint-cards.md" target="_blank" rel="noreferrer">hint cards</a> one at a time, then tutor mode (🟡 AI limited). Try every bug yourself before you look anything else up</td></tr><tr><td><strong>Oral walkthroughs</strong> (weeks 8, 12, 14)</td><td>Record a 5–10 minute screen video with the AI off: explain one function, change something live, and find a bug from an error message, using each walkthrough&#39;s question bank in <a href="./../assessment/oral-walkthroughs.html">Oral Walkthroughs</a>. See <a href="#checking-yourself-the-six-skills">checking yourself</a></td></tr><tr><td><strong>Peer review</strong></td><td>Review a public project with the <a href="./../templates/CODE_REVIEW.html">review checklist</a>, then compare your review with an AI review of the same code</td></tr><tr><td><strong>Grades</strong></td><td>Score yourself with the <a href="./../assessment/rubrics.html">rubrics</a>. Be honest: a score you inflate tells you nothing</td></tr><tr><td><strong>Project Fair</strong> (week 16)</td><td>See <a href="#working-alone-every-pair-activity">week 16</a> below</td></tr></tbody></table><h2 id="working-alone-every-pair-activity" tabindex="-1">Working alone? Every pair activity <a class="header-anchor" href="#working-alone-every-pair-activity" aria-label="Permalink to &quot;Working alone? Every pair activity&quot;">​</a></h2><p>Each lab marks its pair activities with a <strong>Working alone?</strong> line. Here they all are in one place.</p><table tabindex="0"><thead><tr><th>Week</th><th>Pair or group activity</th><th>Working alone</th></tr></thead><tbody><tr><td>1</td><td><strong>Checkpoint share:</strong> show a neighbor one line you changed by hand</td><td>Write one sentence in your notes: which line you changed by hand, and what it does</td></tr><tr><td>3</td><td><strong>Playtest</strong> a classmate&#39;s game</td><td>Play your own game with the lab&#39;s edge cases, then ask someone at home to try it for two minutes later in the week</td></tr><tr><td>4</td><td><strong>Two-model comparison:</strong> share your result with the class</td><td>Write the URL and the count in your notes</td></tr><tr><td>4</td><td><strong>Peer explanation swap</strong> (🔴 AI off): explain a function in a classmate&#39;s game</td><td>Pick a function in your own game, write the four answers from <a href="./without-ai-skills.html#2-explain-any-function-you-committed">skill 2</a> without AI, and explain it out loud to a friend or to your phone&#39;s recorder. Only then compare with an AI explanation</td></tr><tr><td>4</td><td><strong>Prompt makeover:</strong> a partner checks your rewrite</td><td>Check your rewrite against the four parts yourself, put it away for ten minutes, then read it again as if you were the AI</td></tr><tr><td>5</td><td><strong>Peer spec review</strong> (written)</td><td><em>Enrolled:</em> review the instructor&#39;s practice spec; that written review is the graded one. <em>On your own:</em> read your spec aloud as if you were a stranger, ask a friend to predict what app it describes, and let the <a href="./prompt-patterns.html#18-the-goldfish-test">Goldfish test</a> play the reviewer</td></tr><tr><td>6</td><td><strong>Builder bake-off</strong> jigsaw: compare scorecards with a partner who tested the other builder</td><td>Test both builders if your credits allow (allow 40 minutes), or test one and score it against your own spec&#39;s criteria. <em>Enrolled:</em> compare with the class results board</td></tr><tr><td>7</td><td><strong>Debug Clinic</strong> in pairs (driver and navigator)</td><td>Be your own navigator: before you change any code, say each step out loud or type it into <code>BUGS.md</code></td></tr><tr><td>7</td><td><strong>Explain a function</strong> of Project 1 to your partner</td><td>Explain it out loud or on a recording, line by line. Anything you can&#39;t explain goes on your homework list</td></tr><tr><td>11</td><td><strong>Be the Agent:</strong> one person plays the Model, one the Harness</td><td>Play the Harness yourself and let a chat assistant play the Model: in a fresh chat, paste the kit&#39;s task card and tool cards and ask it for one tool call at a time. You carry out each call and paste back only the result. <em>Enrolled:</em> the instructor may play the Model, then you swap</td></tr><tr><td>12</td><td><strong>Feature clinic</strong> stations</td><td>Pick the station your capstone needs (a chart or an external API) and follow its worked example in the lab</td></tr><tr><td>14</td><td><strong>Case-study jigsaw</strong> (groups of three)</td><td>Read <a href="./case-studies.html#using-these-in-class">cases 12, 13 and 14</a> and write the four lines for each</td></tr><tr><td>14</td><td><strong>AI-off maintenance task:</strong> a partner picks your change card</td><td><em>Enrolled:</em> your instructor sends you a card at the start. <em>On your own:</em> number the lab&#39;s change cards and pick one at random (roll a die) before you look at your code</td></tr><tr><td>14</td><td><strong>Peer review as a pull-request review</strong> (🔴 AI off)</td><td><em>Enrolled:</em> review the practice pull request your instructor assigns; it has known issues to find. <em>On your own:</em> a day after opening your week 12 pull request, review it yourself against <a href="./../templates/CODE_REVIEW.html">CODE_REVIEW.md template</a> in the <strong>Files changed</strong> tab, then compare with an AI review</td></tr><tr><td>14</td><td><strong>Handoff test:</strong> a partner makes one change using only your <code>README.md</code> and <code>AGENTS.md</code></td><td><em>Enrolled:</em> your instructor, or a volunteer with a fresh GitHub account, is the tester. <em>On your own:</em> ask a friend, or be the goldfish yourself: a week later, fork your repo, open a fresh Codespace and a fresh agent session, and give it only your <code>README.md</code>, <code>AGENTS.md</code> and one small change request. Note every gap it hits</td></tr><tr><td>15</td><td><strong>Pitch practice:</strong> a partner fills in a feedback card</td><td>Record your 60–90 second pitch, watch it back, and fill in the <a href="./../weeks/16-project-fair/project-fair.html">feedback card</a> yourself</td></tr><tr><td>16</td><td><strong>Project Fair</strong></td><td><em>Enrolled:</em> a public demo slot your instructor arranges, plus three outside testers. <em>On your own:</em> three testers (friends, family or an online community) each try your app on made-up data and fill in the feedback card, and you record a 2–3 minute demo video</td></tr><tr><td>11–16</td><td><strong>Pair capstones</strong></td><td>Not available when you work alone. A solo capstone needs at least two of the four feature types, where a pair needs three (<a href="./../projects/capstone.html">Capstone (weeks 11–16)</a>)</td></tr></tbody></table><h2 id="using-tutor-mode" tabindex="-1">Using tutor mode <a class="header-anchor" href="#using-tutor-mode" aria-label="Permalink to &quot;Using tutor mode&quot;">​</a></h2><p><strong>Tutor mode</strong> is an AI that gives hints and asks questions instead of handing you answers. Working alone, it&#39;s the nearest thing to a TA. It&#39;s set up by pasting one prompt into a fresh chat.</p><p><strong>When to use it:</strong></p><ul><li>🟡 AI limited: in the <strong>Debug Clinic</strong>, after 10 minutes stuck on one bug. It&#39;s the only AI allowed there.</li><li>When you want to <em>learn</em> something, not just get it done, in any homework.</li><li>To practice for an oral walkthrough: the &quot;quiz me&quot; prompt asks you questions about your own code.</li></ul><p><strong>How:</strong></p><ol><li>Open a <strong>new</strong> chat, a temporary one if your assistant offers it.</li><li>Paste the tutor prompt from the <a href="./tutor-mode.html#the-tutor-prompt">tutor mode page</a>. (Gemini users can save it as a Gem: <a href="./tutor-mode.html#build-it-as-a-shared-gemini-gem">how</a>.)</li><li>Describe your problem: what you&#39;re working on, the exact error text, and what you think is wrong. End with &quot;Give me a hint, not the answer.&quot; An example is in <a href="./prompt-patterns.html#14-tutor-mode">prompt pattern 14</a>.</li><li>If it hands you the answer, paste the prompt again or start a fresh chat. If a hint doesn&#39;t help, ask for a smaller one.</li></ol><p>For walkthrough practice, use the <a href="./tutor-mode.html#a-second-prompt-quiz-me">quiz-me prompt</a> on a function you committed.</p><p><strong>Keep it narrow.</strong> Use tutor mode for being stuck and for practice, not as a companion for every step. In a 2026 trial with 2,379 students, giving every student a course-wide AI tutor <em>lowered</em> final grades, most of all for first-generation students; the authors think it pulled students away from the course&#39;s own activities (<a href="https://edworkingpapers.com/ai26-1598" target="_blank" rel="noreferrer">EdWorkingPapers</a>). Do the lab, then ask for a hint. More on why: <a href="./tutor-mode.html#keep-tutor-mode-narrow">tutor mode</a>.</p><h2 id="checking-yourself-the-six-skills" tabindex="-1">Checking yourself: the six skills <a class="header-anchor" href="#checking-yourself-the-six-skills" aria-label="Permalink to &quot;Checking yourself: the six skills&quot;">​</a></h2><p>The course asks you to show <a href="./without-ai-skills.html">six skills with the AI off</a>. Without an examiner, check them this way:</p><ol><li><strong>Practice each skill</strong> with the exercises on <a href="./without-ai-skills.html">Six Skills You Must Show Without AI</a>, answers hidden until you&#39;ve tried.</li><li><strong>Record a walkthrough</strong> in weeks 8, 12 and 14: AI off (close the chat and switch off code suggestions: <a href="./../setup/codespaces.html#turn-copilot-off-for-ai-off-activities">how</a>), screen and voice recording on, about 10 minutes. Use the questions for that walkthrough in <a href="./../assessment/oral-walkthroughs.html">Oral Walkthroughs</a>, picking them at random so you can&#39;t rehearse the answer. Read <a href="./../assessment/oral-walkthroughs.html#what-to-expect">what to expect</a> first.</li><li><strong>Watch it back</strong> and mark each skill on <a href="./without-ai-skills.html#how-the-requirement-works">the list</a> as <em>shown</em> (done correctly, with no more than one look at your notes) or <em>not yet</em>.</li><li><strong>Better still, find a questioner:</strong> a friend reading the questions aloud makes it much closer to the real thing, even if they don&#39;t code.</li></ol><p>A self-check is weaker than an examiner, so be strict with yourself. Any skill that&#39;s still <em>not yet</em> is next week&#39;s practice.</p><h2 id="your-private-writing" tabindex="-1">Your private writing <a class="header-anchor" href="#your-private-writing" aria-label="Permalink to &quot;Your private writing&quot;">​</a></h2><p>Your <strong>code and project documents</strong> (<code>SPEC.md</code>, <code>TESTS.md</code>, <code>PROMPTS.md</code>, <code>AGENTS.md</code>, READMEs) belong in public repositories under your GitHub username: they&#39;re your portfolio. Your <strong>personal writing</strong> does not: reflections, your <a href="./glossary.html#ai-journal">AI journal</a>, your personal AI-use rules, self-assessments and reviews of other people&#39;s work.</p><ul><li><em>Enrolled:</em> submit it on <a href="./glossary.html#canvas-lms">Canvas</a>, as everyone does (<a href="./../assessment/#privacy-of-your-work">privacy of your work</a>).</li><li><em>On your own:</em> keep it in a private document or notebook. Never commit it to a public repository, and never name other people in your repos.</li></ul><h2 id="if-you-fall-behind" tabindex="-1">If you fall behind <a class="header-anchor" href="#if-you-fall-behind" aria-label="Permalink to &quot;If you fall behind&quot;">​</a></h2><ul><li>Do each week&#39;s <strong>Minimum to keep up</strong> box first. Every week builds on the one before.</li><li><strong>Project 1 not working by week 7?</strong> A rescue starter, a small working app built from the course&#39;s <a href="./../weeks/05-spec-first/example-spec.html">example spec</a>, lets you keep going: <a href="https://github.com/Boyu-Zhang-UOI/vc101-rescue-study-timer" target="_blank" rel="noreferrer">projects/rescue-starters/study-timer/</a>.</li><li><strong>Out of free credits?</strong> Switch to the fallback (<a href="./troubleshooting.html#i-ran-out-of-free-credits">how</a>). That&#39;s a planned drill, not a failure.</li><li><strong>Stuck for real?</strong> Write <a href="./prompt-patterns.html#6-the-good-bug-report">a good bug report</a>. Writing it often shows you the answer; if not, it&#39;s exactly what to bring to office hours if you&#39;re enrolled, or to share with someone who can help if you&#39;re not.</li><li><strong>Answer keys</strong> for the course&#39;s exercises exist for instructors. Looking at them before you&#39;ve tried turns an exercise into reading. Try first.</li></ul>',37)])])}const m=t(s,[["render",n]]);export{g as __pageData,m as default};
